// SPDX-License-Identifier: GPL-3.0-or-later
// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// SPDX-License-Identifier: GPL-3.0-or-later
// Stable compaction of the seven reserved clipping slots per source triangle.
// Keep positions/weights in their original slots; assembly follows this map
// before allocating the much larger interpolated attribute streams. The high
// bit distinguishes a mapped source slot (including slot zero) from the legacy
// 0/1 validity array used by small passes without a sizing readback.
__global__ void prefix_clip_blocks(const unsigned long long* omw_pages_valid,const unsigned long long* omw_pages_offsets,const unsigned long long* omw_pages_blocks,unsigned int slot_count) {
OmwPaged<const unsigned int> valid(omw_pages_valid);
OmwPaged<unsigned int> offsets(omw_pages_offsets);
OmwPaged<unsigned int> blocks(omw_pages_blocks);

    unsigned int block=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    unsigned int first=block*256u;
    if(first>=slot_count)return;
    unsigned int total=0u;
    for(unsigned int i=first;i<slot_count&&i<first+256u;i++) {
        offsets[i]=total;
        if(valid[i]!=0u)total++;
    }
    blocks[block]=total;
}

__global__ void prefix_clip_totals(const unsigned long long* omw_pages_blocks,const unsigned long long* omw_pages_summary,
    unsigned int block_count) {
OmwPaged<unsigned int> blocks(omw_pages_blocks);
OmwPaged<unsigned int> summary(omw_pages_summary);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i!=0u)return;
    unsigned int total=0u;
    for(unsigned int block=0u;block<block_count;block++) {
        unsigned int count=blocks[block];blocks[block]=total;total+=count;
    }
    summary[0]=total;
}

__global__ void scatter_clip_slots(const unsigned long long* omw_pages_valid,const unsigned long long* omw_pages_offsets,const unsigned long long* omw_pages_blocks,const unsigned long long* omw_pages_compact_valid,unsigned int slot_count) {
OmwPaged<const unsigned int> valid(omw_pages_valid);
OmwPaged<const unsigned int> offsets(omw_pages_offsets);
OmwPaged<const unsigned int> blocks(omw_pages_blocks);
OmwPaged<unsigned int> compact_valid(omw_pages_compact_valid);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i>=slot_count||valid[i]==0u)return;
    compact_valid[blocks[i/256u]+offsets[i]]=0x80000000u|i;
}
